BEGIN;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='domus_knowledge_runtime')THEN CREATE ROLE domus_knowledge_runtime NOLOGIN NOBYPASSRLS;ELSE ALTER ROLE domus_knowledge_runtime NOLOGIN NOBYPASSRLS;END IF;END $$;
GRANT USAGE ON SCHEMA domus_security TO domus_knowledge_runtime;GRANT EXECUTE ON FUNCTION domus_security.current_uuid(text) TO domus_knowledge_runtime;
CREATE TABLE knowledge_asset(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,asset_id uuid NOT NULL,source_id uuid NOT NULL,owner_id uuid NOT NULL,classification text NOT NULL CHECK(classification IN('public','internal','confidential','restricted')),media_type text NOT NULL CHECK(char_length(media_type) BETWEEN 1 AND 160),retention_days integer NOT NULL CHECK(retention_days BETWEEN 1 AND 3650),created_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(tenant_id,workspace_id,asset_id),FOREIGN KEY(tenant_id,workspace_id,source_id)REFERENCES source_registry(tenant_id,workspace_id,source_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,owner_id)REFERENCES iam_user(tenant_id,user_id)ON DELETE RESTRICT);
CREATE TABLE knowledge_asset_version(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,source_id uuid NOT NULL,owner_id uuid NOT NULL,classification text NOT NULL CHECK(classification IN('public','internal','confidential','restricted')),media_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 104857600),checksum text NOT NULL CHECK(checksum~'^sha256:[a-f0-9]{64}$'),bucket_key text NOT NULL CHECK(bucket_key IN('originals','quarantine')),object_key text NOT NULL CHECK(object_key~'^tenant/[0-9a-f-]{36}/workspace/[0-9a-f-]{36}/source/[0-9a-f-]{36}/asset/[0-9a-f-]{36}/version/[0-9a-f-]{36}/blob$'),object_version text NOT NULL CHECK(char_length(object_version) BETWEEN 1 AND 256),retention_days integer NOT NULL CHECK(retention_days BETWEEN 1 AND 3650),state text NOT NULL CHECK(state IN('pending_scan','available','quarantined','rejected','archived','deletion_pending','deleted')),legal_hold boolean NOT NULL DEFAULT false,policy_version text NOT NULL,created_at timestamptz NOT NULL,deleted_at timestamptz,version bigint NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(tenant_id,workspace_id,asset_id,version_id),FOREIGN KEY(tenant_id,workspace_id,asset_id)REFERENCES knowledge_asset(tenant_id,workspace_id,asset_id)ON DELETE RESTRICT,CHECK((state='deleted')=(deleted_at IS NOT NULL)),UNIQUE(tenant_id,workspace_id,object_key,object_version));
CREATE TABLE knowledge_object_audit(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,audit_id uuid NOT NULL,request_id uuid NOT NULL,actor_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,operation text NOT NULL,attributes jsonb NOT NULL,occurred_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workspace_id,audit_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_asset_version(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT);
CREATE TABLE knowledge_object_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.object.accepted.v1','knowledge.object.quarantined.v1','knowledge.object.rejected.v1','knowledge.object.deletion_pending.v1','knowledge.object.deleted.v1','knowledge.object.restore_verified.v1')),request_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,source_id uuid NOT NULL,classification text NOT NULL,state text NOT NULL,checksum text NOT NULL,item_size_bytes bigint NOT NULL,occurred_at timestamptz NOT NULL,attributes jsonb NOT NULL DEFAULT'{}'::jsonb,published_at timestamptz,delivery_attempts integer NOT NULL DEFAULT 0 CHECK(delivery_attempts>=0),PRIMARY KEY(tenant_id,workspace_id,event_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_asset_version(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT);
CREATE OR REPLACE FUNCTION protect_knowledge_object_identity()RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$BEGIN IF(OLD.checksum,OLD.object_key,OLD.object_version,OLD.size_bytes,OLD.source_id,OLD.classification)IS DISTINCT FROM(NEW.checksum,NEW.object_key,NEW.object_version,NEW.size_bytes,NEW.source_id,NEW.classification)THEN RAISE EXCEPTION'KNOWLEDGE_OBJECT_IMMUTABLE';END IF;RETURN NEW;END$$;CREATE TRIGGER knowledge_object_immutable BEFORE UPDATE ON knowledge_asset_version FOR EACH ROW EXECUTE FUNCTION protect_knowledge_object_identity();
REVOKE ALL ON knowledge_asset,knowledge_asset_version,knowledge_object_audit,knowledge_object_outbox FROM PUBLIC;GRANT SELECT,INSERT ON knowledge_asset,knowledge_object_audit,knowledge_object_outbox TO domus_knowledge_runtime;GRANT SELECT,INSERT,UPDATE(state,legal_hold,deleted_at,version)ON knowledge_asset_version TO domus_knowledge_runtime;
ALTER TABLE knowledge_asset ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_asset FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_asset_version ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_asset_version FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_object_audit ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_object_audit FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_object_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_object_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY knowledge_asset_scope ON knowledge_asset TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_asset_version_scope ON knowledge_asset_version TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_object_audit_scope ON knowledge_object_audit TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_object_outbox_scope ON knowledge_object_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(13,'V1-403 immutable knowledge object lineage and lifecycle')ON CONFLICT(version)DO NOTHING;COMMIT;
